.dwi-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dwi-root,.dwi-root *,.dwi-root *::before,.dwi-root *::after{box-sizing:border-box}
.dwi-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dwi-root img{display:block;border:0;max-width:none}
.dwi-root > [data-node-id]{will-change:transform}
.dwi-root [hidden]{display:none!important}
.dwi-root [data-sh-theme="dark"]{display:none!important}
.dwi-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dwi-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dwi-root .n1_3913{align-content:stretch;display:flex;gap:6.617px;height:22px;align-items:center;padding-left:8px;position:relative;flex-shrink:0;width:100%}
.dwi-root .n1_3914{position:relative;flex-shrink:0;width:12px;height:12px}
.dwi-root .x1{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dwi-root .n1_3918{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:19px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #171d25);font-size:16px;white-space:nowrap;width:56px}
.dwi-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.dwi-root[data-theme="dark"] [data-name="Header"] > [data-name="Background"]{background:var(--wa-bg, #131519)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.06)!important}
.dwi-root[data-theme="dark"] [data-name="Input"],.dwi-root[data-theme="dark"] [data-name="Select"],.dwi-root[data-theme="dark"] [data-name^="Field/ID"],.dwi-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
.dwi-root[data-theme="dark"] [data-name="Widget/Notice"] > div:first-child,.dwi-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:first-child,.dwi-root[data-theme="dark"] [data-name="Panel"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 64%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 76%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px) saturate(1.15)!important;-webkit-backdrop-filter:blur(18px) saturate(1.15)!important}
.dwi-root[data-theme="dark"] [data-name="Widget/Notice"] > div:nth-child(3),.dwi-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:nth-child(3),.dwi-root[data-theme="dark"] [data-name="Panel"] > div:nth-child(3){box-shadow:inset 0 1px 0 rgba(255,255,255,.1),inset 0 0 0 1px rgba(255,255,255,.07),0 24px 48px rgba(0,0,0,.34)!important}
.dwi-root[data-theme="dark"] > [data-node-id]:has([data-name^="Widget/"]) > [data-name="Header"] > [data-name="Background"]{background:color-mix(in srgb, var(--wa-bg, rgb(14 16 20)) 68%, transparent)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwi-root[data-theme="dark"] [data-name^="Step/"] > div:first-child{background-color:color-mix(in srgb, var(--wa-point, rgb(130 155 255)) 12%, transparent)}
.dwi-root[data-theme="dark"] [data-name^="Widget/"] [data-name="List Item/Post"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 4.5%, transparent)}
.dwi-root[data-theme="dark"] [data-name="Count"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent)!important}
.dwi-root[data-theme="dark"] [data-name="Login Card"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 62%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 74%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwi-root[data-theme="dark"] [data-name="Login Card"] > div:nth-child(2){box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 0 0 1px rgba(255,255,255,.08),0 30px 60px rgba(0,0,0,.4)!important}
.dwi-root[data-theme="dark"] [data-name="Search Overlay"] > [data-name="Background"],.dwi-root[data-theme="dark"] [data-name="Background"][data-node-id="1:6533"]{background-color:var(--wa-surface, #17191e)!important}
.dwi-root[data-theme="dark"] .n1_3918{color:var(--wa-text, #eceef2)}
